const text = ($json.text ?? '').trim();

if (!text) {
  throw new Error('The TXT file is empty.');
}

const source = $('Google Drive Trigger').first().json;
const originalName = source.name ?? 'tts.txt';

// Remove .txt extension
const baseName = originalName.replace(/\.txt$/i, '');

// Target chunk size
const TARGET_WORDS = 400;

// Don't leave a very small final chunk.
// If the final chunk is below this size, merge it with the previous chunk.
const MIN_FINAL_WORDS = 150;

// Normalize line endings
const normalized = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

// Split into paragraphs
const paragraphs = normalized
  .split(/\n\s*\n+/)
  .map(p => p.trim())
  .filter(Boolean);

// Count words
function wordCount(str) {
  return str.split(/\s+/).filter(Boolean).length;
}

// Split a long paragraph into sentences
function splitLongParagraph(paragraph) {
  const sentences = paragraph.match(/[^.!?]+[.!?]+(?:["'”’)]*)|[^.!?]+$/g);

  if (!sentences) {
    return [paragraph];
  }

  return sentences.map(s => s.trim()).filter(Boolean);
}

// First turn paragraphs into manageable units.
// Normal paragraphs stay intact; very long paragraphs are split into sentences.
const units = [];

for (const paragraph of paragraphs) {
  if (wordCount(paragraph) <= TARGET_WORDS) {
    units.push(paragraph);
  } else {
    units.push(...splitLongParagraph(paragraph));
  }
}

// Build chunks while preserving paragraph/sentence boundaries
const chunks = [];
let current = [];
let currentWords = 0;

for (const unit of units) {
  const words = wordCount(unit);

  // If adding this unit would make the chunk too large,
  // start a new chunk — but don't create an empty chunk.
  if (
    current.length > 0 &&
    currentWords + words > TARGET_WORDS
  ) {
    chunks.push(current.join('\n\n'));
    current = [];
    currentWords = 0;
  }

  current.push(unit);
  currentWords += words;
}

// Add final chunk
if (current.length > 0) {
  chunks.push(current.join('\n\n'));
}

// Merge a very small final chunk into the previous chunk
if (
  chunks.length > 1 &&
  wordCount(chunks[chunks.length - 1]) < MIN_FINAL_WORDS
) {
  const last = chunks.pop();

  chunks[chunks.length - 1] =
    chunks[chunks.length - 1] + '\n\n' + last;
}

// Return one n8n item per chunk
return chunks.map((chunk, index) => ({
  json: {
    text: chunk,
    baseName,
    chunkNumber: index + 1,
    wordCount: wordCount(chunk),
    totalChunks: chunks.length,
    sourceFileId: source.id
  }
}));

