// Pass through the original source file ID and record that this chunk uploaded.
// Archive should be handled only after ALL chunks have succeeded.
const meta = $('Split Into Chunks').item.json;
return {json: {...meta, uploaded: true}};

// This node runs once after ALL WAV uploads have completed.
// If any Gemini TTS or Google Drive upload failed, n8n stops before reaching here,
// so the source TXT is not archived.
const sourceFileId = $('Google Drive Trigger').first().json.id;
const sourceName = $('Google Drive Trigger').first().json.name;

return [{
  json: {
    sourceFileId,
    sourceName,
    status: 'all WAV chunks uploaded successfully'
  }
}];

function findAudio(node) {
  if (!node || typeof node !== 'object') {
    return null;
  }

  // Current Interactions API audio content
  if (
    node.type === 'audio' &&
    typeof node.data === 'string'
  ) {
    return node;
  }

  if (Array.isArray(node)) {
    for (const item of node) {
      const result = findAudio(item);
      if (result) return result;
    }
  } else {
    for (const value of Object.values(node)) {
      const result = findAudio(value);
      if (result) return result;
    }
  }

  return null;
}

const audio = findAudio($json);

if (!audio) {
  throw new Error(
    'No audio content block was found in the Gemini response.'
  );
}

const chunk = $('Split Into Chunks').item.json;

// Gemini TTS returns raw PCM audio.
// Google documents this as:
// 24 kHz, mono, 16-bit PCM.
const pcm = Buffer.from(audio.data, 'base64');

const sampleRate = audio.sample_rate || 24000;
const channels = audio.channels || 1;
const bitsPerSample = 16;

const byteRate =
  sampleRate * channels * bitsPerSample / 8;

const blockAlign =
  channels * bitsPerSample / 8;

const dataSize = pcm.length;

// Standard 44-byte WAV header
const header = Buffer.alloc(44);

header.write('RIFF', 0);
header.writeUInt32LE(36 + dataSize, 4);
header.write('WAVE', 8);

header.write('fmt ', 12);
header.writeUInt32LE(16, 16);
header.writeUInt16LE(1, 20); // PCM
header.writeUInt16LE(channels, 22);
header.writeUInt32LE(sampleRate, 24);
header.writeUInt32LE(byteRate, 28);
header.writeUInt16LE(blockAlign, 32);
header.writeUInt16LE(bitsPerSample, 34);

header.write('data', 36);
header.writeUInt32LE(dataSize, 40);

const wav = Buffer.concat([header, pcm]);

const baseName =
  chunk.baseName.replace(/\.txt$/i, '');

const fileName =
  `${baseName}_${String(chunk.chunkNumber).padStart(3, '0')}.wav`;

return {
  json: {
    ...chunk,
    fileName,
    mimeType: 'audio/wav',
    audioBytes: wav.length,
    sampleRate,
    channels
  },

  binary: {
    data: {
      data: wav.toString('base64'),
      mimeType: 'audio/wav',
      fileName,
      fileExtension: 'wav'
    }
  }
};
